{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms, ROUND(AVG(duration/1e6),1) avg_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name IN ('ts-route-service') AND span_name ILIKE '%ts.route%' GROUP BY ALL ORDER BY 2,3,1",
          "claim": "Route-service SELECTs on ts.route_distances and ts.route_stations rose from ~0.1 ms p95 to ~430 ms p95; the same service's INSERT/DELETE calls stayed fast."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_k8s_pod_name pod, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6, 0.95),1) p95_ms, SUM(CASE WHEN attr_status_code='ERROR' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('ts-route-service') GROUP BY ALL ORDER BY 3,4",
          "claim": "Route-service Server spans for /routeservice/routes reach ~56 s p95 with its own repository and DB spans slow, but no span errors recorded."
        },
        {
          "kind": "metric",
          "sql": "SELECT p, service_name, attr_k8s_pod_name pod, metric, COUNT(*) n, ROUND(AVG(value),3) avg_v, ROUND(MAX(value),3) max_v FROM (SELECT 'abn' p,* FROM abnormal_metrics UNION ALL SELECT 'norm',* FROM normal_metrics) WHERE service_name='mysql' AND metric IN ('k8s.pod.cpu.usage','container.memory.working_set') GROUP BY ALL ORDER BY metric, p",
          "claim": "Mysql CPU and memory stayed flat or fell during the incident, so the database server itself was not saturated."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name ILIKE '%routeservice/routes%' GROUP BY ALL ORDER BY 3,1",
          "claim": "User-facing GET /api/v1/routeservice/routes at ui-dashboard rose from ~40 ms to ~20 s p95 as route-service calls slowed."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name ILIKE '%adminrouteservice/adminroute%' GROUP BY ALL ORDER BY 3,1",
          "claim": "Admin route endpoint at ui-dashboard rose from ~45 ms to ~20 s p95, consistent with the route-service dependency."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-service') AND attr_span_kind='Server' GROUP BY ALL ORDER BY 2",
          "claim": "Travel-service Server spans slowed to ~5.9 s p95 in the abnormal period, while its DB spans stayed fast; its time sits in the route-service call."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Admin-travel server spans slowed in the abnormal period, consistent with calls to travel-service that slowed."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration/1e6,0.95),1) p95_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name ILIKE '%admintravelservice/admintravel%' GROUP BY ALL ORDER BY 3,1",
          "claim": "User-facing admin travel endpoint at ui-dashboard rose from ~44 ms to ~9.9 s p95."
        }
      ]
    }
  ]
